      position: absolute;
      left: 1rem;
      top: 1rem;
      padding: 0.8rem 1rem;
      border-radius: 999px;
      background: var(--surface-strong);
      color: var(--text);
      text-decoration: none;
      transform: translateY(-220%);
      transition: transform 0.2s ease;
      z-index: 10;
      box-shadow: var(--shadow);
    }

    .skip-link:focus {
      transform: translateY(0);
    }

