      aspect-ratio: 5 / 4;
      margin: 0;
      background:
        linear-gradient(135deg, rgba(255, 255, 255, 0.18), transparent),
        url("https://images.unsplash.com/photo-1511300636408-a63a89df3482?auto=format&fit=crop&w=1200&q=80") center / cover no-repeat;
    }

    .preview-body {
      padding: 1.25rem;
    }

    .preview-meta {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 1rem;
      margin-bottom: 1rem;
    }

    .preview-title {
      margin: 0;
      font-size: 1.15rem;
      font-weight: 700;
    }

    .preview-copy {
      margin: 0.35rem 0 0;
      color: var(--muted);
      line-height: 1.5;
    }

    .badge {
      padding: 0.45rem 0.7rem;
      border-radius: 999px;
      background: rgba(23, 32, 51, 0.06);
      color: var(--muted);
      font-size: 0.88rem;
      white-space: nowrap;
    }

    .button-row {
      display: flex;
      flex-wrap: wrap;
      gap: 0.75rem;
    }

    button {
      min-height: 44px;
      padding: 0.85rem 1.2rem;
      border: 1px solid transparent;
      border-radius: 999px;
      cursor: pointer;
      transition: background-color 0.2s ease, color 0.2s ease, border-color 0.2s ease, transform 0.2s ease;
    }

    button:hover {
      transform: translateY(-1px);
    }

    .secondary-button {
      border-color: var(--border);
      background: #fff;
      color: var(--text);
    }

    .secondary-button:hover {
      background: #f9fbff;
    }

    .danger-button {
      background: var(--danger);
      color: #fff;
    }

    .danger-button:hover {
      background: var(--danger-strong);
    }

    .dialog-actions {
      display: flex;
      justify-content: flex-end;
      flex-wrap: wrap;
      gap: 0.75rem;
      margin-top: 1.5rem;
    }

    .supporting-panel {
      display: grid;
      gap: 1rem;
    }

    .panel {
      padding: 1.25rem;
      border: 1px solid var(--border);
      border-radius: var(--radius-lg);
      background: rgba(255, 255, 255, 0.78);
    }

    .panel h2 {
      margin: 0 0 0.75rem;
      font-size: 1rem;
    }

    .panel p,
    .panel li {
      color: var(--muted);
      line-height: 1.55;
    }

    .panel ul {
      margin: 0;
      padding-left: 1.2rem;
    }

    dialog {
      width: min(100% - 2rem, 30rem);
      padding: 0;
      border: none;
      border-radius: 24px;
      background: var(--surface-strong);
      box-shadow: 0 36px 72px rgba(15, 23, 42, 0.28);
    }

    dialog::backdrop {
      background: rgba(11, 18, 32, 0.6);
      backdrop-filter: blur(5px);
    }

    .dialog-card {
      padding: 1.5rem;
    }

    .dialog-icon {
      display: inline-grid;
      place-items: center;
      width: 3rem;
      height: 3rem;
      border-radius: 999px;
      background: rgba(209, 65, 91, 0.12);
      color: var(--danger);
      font-size: 1.4rem;
      font-weight: 700;
    }

    .dialog-title {
      margin: 1rem 0 0.55rem;
      font-size: 1.4rem;
      line-height: 1.2;
    }

    .dialog-copy {
      margin: 0;
      color: var(--muted);
      line-height: 1.6;
    }

    .status {
      min-height: 1.5rem;
      margin-top: 1rem;
      color: var(--muted);
      font-size: 0.95rem;
    }

    :focus-visible {
      outline: 3px solid var(--focus);
      outline-offset: 3px;
    }

    @media (max-width: 860px) {
      .hero {
        grid-template-columns: 1fr;
