      header {
        flex-direction: column;
        align-items: flex-start;
      }

      .preview-meta {
        flex-direction: column;
        align-items: flex-start;
      }

      .dialog-actions,
      .button-row {
        flex-direction: column;
      }

      .dialog-actions button,
      .button-row button {
        width: 100%;
      }
    }

