        box-shadow: none;
      }

      .eyebrow,
      .badge,
      .dialog-icon,
      .secondary-button,
      .danger-button {
        border: 1px solid ButtonText;
        background: ButtonFace;
        color: ButtonText;
      }

      dialog::backdrop {
        background: rgba(0, 0, 0, 0.7);
      }
    }
  </style>
