<body>
  <a class="skip-link" href="#maincontent">Skip to main content</a>

  <div class="page-shell">
    <header>
      <a class="brand" href="#" aria-label="PixelBin home">PixelBin</a>
      <nav aria-label="Primary">
        <ul>
          <li><a href="#">Library</a></li>
          <li><a href="#">Collections</a></li>
          <li><a href="#">Shared</a></li>
        </ul>
      </nav>
    </header>

    <main id="maincontent" tabindex="-1">
      <section class="hero" aria-labelledby="page-title">
        <div>
          <span class="eyebrow">Image preview</span>
          <h1 id="page-title">Review your image before removing it from the library.</h1>
          <p class="lead">
            Double-check the preview, metadata, and usage before taking action. If you choose to delete this image,
            it will be removed from your library immediately.
          </p>
          <p class="status" id="status-message" aria-live="polite"></p>
        </div>

        <div class="supporting-panel">
          <article class="preview-card" aria-labelledby="image-title">
            <figure class="preview-frame" role="img" aria-label="Sunlit mountains with a lake reflecting the sky"></figure>
            <div class="preview-body">
              <div class="preview-meta">
                <div>
                  <h2 class="preview-title" id="image-title">Alpine Light</h2>
                  <p class="preview-copy">Landscape photo uploaded to your travel collection.</p>
                </div>
                <span class="badge">5.2 MB</span>
              </div>

              <div class="button-row">
                <button class="secondary-button" type="button">Download</button>
                <button class="trigger danger-button" type="button">Delete image</button>
              </div>
            </div>
          </article>

          <aside class="panel" aria-labelledby="details-heading">
            <h2 id="details-heading">Image details</h2>
            <ul>
              <li>Resolution: 4032 x 3024</li>
              <li>Collection: Summer campaign</li>
              <li>Last edited: Today at 10:42 AM</li>
            </ul>
          </aside>
        </div>
      </section>
    </main>
  </div>

  <dialog id="delete-dialog" aria-labelledby="dialog-title" aria-describedby="dialog-description">
    <div class="dialog-card">
      <div class="dialog-icon" aria-hidden="true">!</div>
      <h2 class="dialog-title" id="dialog-title">Delete this image from your library?</h2>
      <p class="dialog-copy" id="dialog-description">
        This image will be removed from the library and won't appear in collections or search results anymore.
      </p>
      <div class="dialog-actions">
        <button class="secondary-button" id="cancel-button" type="button" autofocus>Cancel</button>
        <button class="danger-button" id="confirm-button" type="button">Delete image</button>
      </div>
    </div>
  </dialog>

  <script>
    const trigger = document.querySelector(".trigger");
    const dialog = document.getElementById("delete-dialog");
    const cancelButton = document.getElementById("cancel-button");
    const confirmButton = document.getElementById("confirm-button");
    const statusMessage = document.getElementById("status-message");

    trigger.addEventListener("click", () => {
      dialog.showModal();
    });

    cancelButton.addEventListener("click", () => {
      dialog.close("cancel");
    });

    confirmButton.addEventListener("click", () => {
      dialog.close("delete");
    });

    dialog.addEventListener("click", (event) => {
      const bounds = dialog.getBoundingClientRect();
      const clickedInside =
        event.clientX >= bounds.left &&
        event.clientX <= bounds.right &&
        event.clientY >= bounds.top &&
        event.clientY <= bounds.bottom;

      if (!clickedInside) {
        dialog.close("cancel");
      }
    });

    dialog.addEventListener("close", () => {
      if (dialog.returnValue === "delete") {
        statusMessage.textContent = "Image deleted from your library.";
      } else {
        statusMessage.textContent = "Deletion canceled.";
      }
    });
  </script>
</body>
</html>
